import { Component, OnInit } from '@angular/core';
import { VozackaService, VozackaDozvola } from '../../services/vozacka.service';

@Component({
  selector: 'app-vozacka',
  templateUrl: './vozacka.component.html',
  styleUrls: ['./vozacka.component.css']
})
export class VozackaComponent implements OnInit {

  vozacke: VozackaDozvola[] = []; // ⬅️ dodajemo svojstvo za tabelu
  noviZahtev = { grad: '', kategorijeStr: '' }; // za modal

  constructor(private vozackaService: VozackaService) { }

  ngOnInit(): void {
    this.ucitajVozacke();
  }

  ucitajVozacke(): void {
    this.vozackaService.dohvatiSve().subscribe(res => {
      this.vozacke = res;
    });
  }

  // Funkcija za otvaranje modala (ako koristiš Bootstrap)
  openVozackaModal(): void {
    const modalEl = document.getElementById('vozackaModal');
    if (modalEl) {
      const modal = new bootstrap.Modal(modalEl);
      modal.show();
    }
  }

  // Funkcija za podnošenje zahteva iz modala
  podnesiZahtev(): void {
    const kategorije = this.noviZahtev.kategorijeStr.split(',').map(k => k.trim());
    const payload = { grad: this.noviZahtev.grad, kategorije };
    this.vozackaService.podnesiZahtev(payload).subscribe({
      next: res => {
        console.log(res);
        this.ucitajVozacke(); // osvežava tabelu
      },
      error: err => console.error(err)
    });
  }

}
<div class="container mt-5">

  <!-- Dugme za podnošenje zahteva za vozačku -->
  <div class="d-flex justify-content-center mb-4">
    <button class="btn btn-primary">Zahtev za vađenje vozačke dozvole</button>
  </div>

  <!-- Tabela vozačkih dozvola -->
  <h3 class="mb-3 text-center">Moje vozačke dozvole</h3>
  <div class="table-responsive">
    <table class="table table-striped table-bordered">
      <thead class="table-dark">
      <tr>
        <th>#</th>
        <th>Ime</th>
        <th>Prezime</th>
        <th>Datum rođenja</th>
        <th>Datum izdavanja</th>
        <th>Važi do</th>
        <th>Grad</th>
        <th>Broj dozvole</th>
        <th>Kategorije</th>
        <th>Status</th>
      </tr>
      </thead>
      <tbody>
      <tr>
        <td>1</td>
        <td>Marko</td>
        <td>Marković</td>
        <td>10.05.1990</td>
        <td>18.09.2025</td>
        <td>18.09.2035</td>
        <td>Beograd</td>
        <td>AB12345</td>
        <td>A, B</td>
        <td>DOZVOLJEN</td>
      </tr>
      <tr>
        <td>2</td>
        <td>Jovana</td>
        <td>Jovanović</td>
        <td>22.03.1992</td>
        <td>01.06.2024</td>
        <td>01.06.2034</td>
        <td>Novi Sad</td>
        <td>CD67890</td>
        <td>B, C</td>
        <td>CEKANJE</td>
      </tr>
      </tbody>
    </table>
  </div>

  <!-- Modal za podnošenje zahteva -->
  <div class="modal fade" id="vozackaModal" tabindex="-1" aria-labelledby="vozackaModalLabel" aria-hidden="true">
    <div class="modal-dialog">
      <div class="modal-content">
        <div class="modal-header">
          <h5 class="modal-title" id="vozackaModalLabel">Podnesi zahtev za vozačku dozvolu</h5>
          <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button>
        </div>
        <div class="modal-body">
          <form>
            <div class="mb-3">
              <label for="grad" class="form-label">Grad</label>
              <input type="text" class="form-control" id="grad" placeholder="Unesite grad">
            </div>

            <div class="mb-3">
              <label for="kategorije" class="form-label">Kategorije</label>
              <input type="text" class="form-control" id="kategorije" placeholder="Unesite kategorije odvojene zarezom, npr. A,B">
            </div>

            <div class="modal-footer">
              <button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Zatvori</button>
              <button type="submit" class="btn btn-primary">Podnesi zahtev</button>
            </div>
          </form>
        </div>
      </div>
    </div>
  </div>

</div>
